package br.com.admeclesial.domain.financeiro;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDate; import java.util.UUID;
@Entity @Table(name="destinacao_contribuicao",schema="adm_eclesial") public class DestinacaoContribuicao { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(nullable=false,unique=true,updatable=false) UUID uuid; @Column(name="contribuicao_id",nullable=false) Long contribuicaoId; @Column(name="centro_custo_id") Long centroCustoId; @Enumerated(EnumType.STRING) @Column(nullable=false,length=30) TipoDestinacaoContribuicao tipo; @Column(length=500) String descricao; @Column(nullable=false,precision=15,scale=2) BigDecimal valor; @Column(name="uso_exclusivo",nullable=false) boolean usoExclusivo; @PrePersist void pre(){if(uuid==null)uuid=UUID.randomUUID();} public Long getId(){return id;} public UUID getUuid(){return uuid;} public Long getContribuicaoId(){return contribuicaoId;} public Long getCentroCustoId(){return centroCustoId;} public TipoDestinacaoContribuicao getTipo(){return tipo;} public String getDescricao(){return descricao;} public BigDecimal getValor(){return valor;} public boolean getUsoExclusivo(){return usoExclusivo;} public void setContribuicaoId(Long v){contribuicaoId=v;} public void setCentroCustoId(Long v){centroCustoId=v;} public void setTipo(TipoDestinacaoContribuicao v){tipo=v;} public void setDescricao(String v){descricao=v;} public void setValor(BigDecimal v){valor=v;} public void setUsoExclusivo(boolean v){usoExclusivo=v;} }